import subprocess
import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    # Record start time
    start_time = time.time()

    # Execute the R script
    try:
        subprocess.run(['Rscript', r_script_path], check=False)
    except Exception:
        # Continue even if R script execution fails
        pass

    # Monitor for file creation within the specified duration
    while time.time() - start_time < duration:
        if os.path.exists(output_path):
            return (True, 'File generated successfully within the specified duration.')
        time.sleep(0.1)  # Avoid busy waiting

    # Duration expired without file creation
    return (False, 'File not generated within the specified duration.')

