import subprocess
import pandas as pd
import matplotlib.pyplot as plt
def task_func(script_path, output_file_path):
    # Execute the script
    try:
        result = subprocess.run(['python', script_path], capture_output=True, text=True, check=True)
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Script failed to execute: {e}")
    except FileNotFoundError:
        raise ValueError(f"Script file not found: {script_path}")
    except Exception as e:
        raise ValueError(f"Script failed to execute: {e}")

    # Read the CSV file
    try:
        df = pd.read_csv(output_file_path)
    except FileNotFoundError:
        raise ValueError(f"CSV file not found: {output_file_path}")
    except pd.errors.EmptyDataError:
        raise ValueError("CSV file is empty")
    except Exception as e:
        raise ValueError(f"Failed to read CSV file: {e}")

    # Validate that CSV has exactly 2 columns
    if len(df.columns) != 2:
        raise ValueError(f"CSV must contain exactly 2 columns, but has {len(df.columns)}")

    # Create the bar graph
    fig, ax = plt.subplots()
    ax.bar(df.iloc[:, 0], df.iloc[:, 1])
    ax.set_xlabel(df.columns[0])
    ax.set_ylabel(df.columns[1])
    plt.tight_layout()

    return df, ax

