import subprocess
import time
import json
import platform
from datetime import datetime
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    # Validate inputs
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    cpu_data = []
    start_time = time.time()
    system = platform.system()

    while time.time() - start_time < duration:
        timestamp = datetime.now().isoformat()
        cpu_percent = 0

        try:
            if system == "Windows":
                # Windows: Use wmic to get CPU load percentage
                result = subprocess.run(
                    ["wmic", "cpu", "get", "loadpercentage"],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                lines = result.stdout.strip().split('\n')
                # Skip header and get the value
                for line in lines[1:]:
                    line = line.strip()
                    if line:
                        cpu_percent = int(line)
                        break
            else:
                # Unix/Linux: Use top to get CPU usage
                result = subprocess.run(
                    ["top", "-bn1"],
                    capture_output=True,
                    text=True,
                    timeout=5
                )
                for line in result.stdout.split('\n'):
                    if 'Cpu(s)' in line or '%Cpu' in line:
                        # Extract user CPU percentage
                        parts = line.split(',')
                        for part in parts:
                            part = part.strip()
                            if 'us' in part.lower():
                                try:
                                    cpu_percent = float(part.split()[0])
                                except (ValueError, IndexError):
                                    pass
                                break
                        break
        except Exception:
            cpu_percent = 0

        # Record the data point
        cpu_data.append({
            "timestamp": timestamp,
            "cpu_usage": cpu_percent
        })

        # Wait for the next interval
        time.sleep(interval)

    # Write data to log file
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(cpu_data, f, indent=2)
        return LOGFILE_PATH
    except IOError:
        return None
